  test("rollup audit scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00", "from": "2026-03-01"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    await ui.setToday(pg_uma, "2026-04-26");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00", "from": "2026-03-01"})).toBe(true);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25", "date": "2026-03-01"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.35", "date": "2026-02-10"}));
    expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_0, "void")).toBe(true);
    await ui.refresh(pg_uma);
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.25", "date": "2026-03-01"}));
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_1, "settle")).toBe(true);
    expect(await ui.statement(pg_vic, p_ben)).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    await ui.setToday(pg_wes, "2026-06-04");
    const c_ada_2 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "10.25", "date": "2026-03-05"}));
    await ui.refresh(pg_wes);
    await ui.setToday(pg_wes, "2026-06-24");
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_ada_2, "open")).toBe(true);
    const c_cam_1 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "10.25", "date": "2026-03-01"}));
    expect(await ui.editClaim(pg_vic, c_cam_1, {"amount": "3.33"})).toBe(true);
    await ui.setToday(pg_vic, "2026-07-24");
    await ui.refresh(pg_vic);
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=10.00 from=2026-03-01`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=C`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=n/a`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=C`,
      `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=n/a`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00 from=2026-03-01`,
      `STATEMENT sheet=${sheet} by=uma name=Ada due-total=n/a claims=0`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Cam amount=10.25 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.35 date=2026-02-10`,
      `CLAIM_VOIDED sheet=${sheet} by=uma person=Cam amount=10.25 date=2026-03-01`,
      `CLAIM_VOIDED sheet=${sheet} by=uma person=Ada amount=10.35 date=2026-02-10`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.25 date=2026-03-01`,
