package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_ADDED to the audit file once the claim is stored. */
public class RecordClaimAdded {
    public void record(@Val Claim claim, @Val Person person, @Val ClaimValues values, Audit audit) {
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + values.by() + " person=" + person.name()
                + " amount=" + claim.amount().toPlainString() + " date=" + claim.date());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_EDITED to the audit file once the edit is stored. */
public class RecordClaimEdited {
    public void record(@Val Claim claim, @Val ClaimValues values, PersonRepository people, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_EDITED sheet=" + claim.sheetId() + " by=" + values.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim's values once validated. {@code date} is null when none was given (the sheet's today applies). {@code by} is who gives them. */
public record ClaimValues(BigDecimal amount, LocalDate date, String note, String by) {
}
package net.officefloor.hq.app.person;

/** A person's values once validated, and who gives them; for an edit, the version it was made from (null for an add). */
public record PersonValues(String name, String grade, String by, Long version) {
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;

/**
 * A sheet: everything else in the app is kept per sheet, keyed by its id. {@code today} is the
 * sheet's own date — every date decision and default date on the sheet uses it, never the clock.
 */
public record Sheet(String id, LocalDate today) {
}
# OfficeFloor REST wiring

Domain REST endpoints are declared here as OfficeFloor YAML, served by the
`officefloor-rest-spring-boot-4-starter` inside the Spring Boot host. Put them under `rest/api/` so
their paths start with `/api/` — `SpaConfig` only lets `/api/*` reach the backend; a non-`/api/`
path returns the SPA's `index.html` instead of your endpoint. Directory nesting maps to path
segments, so `rest/api/owners.GET.yml` → `GET /api/owners`. Each route is its own file:

```
# officefloor/rest/api/<path>.GET.yml   (or .POST.yml, {param}.GET.yml, ...)
service:
  class: net.officefloor.hq.app.<SomeLogic>   # a class with a service(...) method
```

The logic class's `service(...)` method takes injected dependencies (Spring `@Service` beans, the
data layer) and a `net.officefloor.web.ObjectResponse<T>` to send the response.

(The `/actuator/health` readiness endpoint is Spring-side — Actuator — not an OfficeFloor route.)

